INSERT INTO "public"."Profile" ("first_name", "surname", "email", "profile_pic", "cv_link", "bio", "user_type", "id") VALUES ('Digital', 'Ventures', 'hiring@digitalventures.com', 'https://profilepics.com/orgs/036.jpg', '', 'Digital Ventures is a venture capital firm investing in early-stage technology startups. We focus on companies leveraging artificial intelligence, blockchain, and IoT technologies to solve real-world problems. Our portfolio includes successful exits and companies that have raised follow-on funding. We provide strategic guidance, industry connections, and operational support to our portfolio companies. Seeking investment analysts, due diligence specialists, and portfolio managers with technology backgrounds.', 'organization', '00cfdc58-6703-4754-8810-e33aaeeb3f99'), ('Nathan', 'Evans', 'nathan.evans@email.com', 'https://profilepics.com/users/052.jpg', 'https://cvs.com/nathan_evans_cv.pdf', 'Physical therapist with 6 years helping patients recover from injuries and improve mobility. Licensed PT with specialty certifications in sports medicine and orthopedic rehabilitation. Treated over 1,000 patients across various conditions including post-surgical recovery, chronic pain, and athletic injuries. Strong communication skills with ability to develop personalized treatment plans. Experience with latest rehabilitation techniques and technologies. Seeking clinical leadership or program management roles.', 'jobseeker', '03b2f88c-ece1-4bae-893c-9eacc4c6047f'), ('Wayne', 'James', 'wayne.james@email.com', 'https://profilepics.com/users/082.jpg', 'https://cvs.com/wayne_james_cv.pdf', 'Truck driver with 16 years experience in long-haul and regional transportation. CDL Class A license with clean driving record and safety awards. Transported freight across 48 states while maintaining on-time delivery and cargo security. Strong customer service skills with experience in logistics coordination and electronic logging devices. Knowledge of DOT regulations, route planning, and vehicle maintenance. Seeking driving opportunities with reputable transportation companies.', 'jobseeker', '04929061-a549-484a-8a1a-d05fa1bd6a4e'), ('Marie', 'Price', 'marie.price@email.com', 'https://profilepics.com/users/089.jpg', 'https://cvs.com/marie_price_cv.pdf', 'Physical education teacher and coach with 8 years promoting health and fitness among students. Masters degree in Kinesiology with certifications in CPR, first aid, and sports medicine. Coached multiple sports teams to championship levels while emphasizing teamwork, discipline, and sportsmanship. Developed fitness programs that improved student health outcomes and participation rates. Strong motivational skills with passion for youth development through athletics.', 'jobseeker', '0565ec1c-0823-4c95-bf95-6d431e072e2d'), ('Helen', 'Bailey', 'helen.bailey@email.com', 'https://profilepics.com/users/065.jpg', 'https://cvs.com/helen_bailey_cv.pdf', 'Pharmacist with 11 years in clinical and retail pharmacy settings. PharmD degree with specialization in geriatric pharmacy and medication therapy management. Provided pharmaceutical care to diverse patient populations while ensuring medication safety and efficacy. Strong consultation skills with experience in drug interactions, dosing optimization, and patient education. Led clinical pharmacy programs that improved patient outcomes and reduced healthcare costs.', 'jobseeker', '092e911c-d069-4036-9baf-9d85a05eda8d'), ('Security', 'Systems', 'careers@securitysystems.com', 'https://profilepics.com/orgs/081.jpg', '', 'Security Systems is a leading provider of physical and cyber security solutions for businesses and government agencies. We design, install, and maintain comprehensive security systems including access control, video surveillance, and intrusion detection. Our certified technicians serve clients across multiple industries with 24/7 monitoring and response services. We are committed to protecting people and assets through innovative security technology. Seeking security specialists and system engineers.', 'organization', '0cd45947-02ca-4ae5-abcc-66f1796d57a0'), ('Cheryl', 'Peterson', 'cheryl.peterson@email.com', 'https://profilepics.com/users/077.jpg', 'https://cvs.com/cheryl_peterson_cv.pdf', 'Social worker with 8 years providing support services to individuals and families in crisis. MSW degree with specialization in clinical social work and case management. Worked in healthcare, school, and community mental health settings serving diverse populations. Strong assessment and intervention skills with experience in trauma-informed care and crisis intervention. Licensed clinical social worker with additional certifications in substance abuse counseling.', 'jobseeker', '1355caf8-c32a-4df5-89fd-b3f1cd7b0004'), ('Carlos', 'Collins', 'carlos.collins@email.com', 'https://profilepics.com/users/055.jpg', 'https://cvs.com/carlos_collins_cv.pdf', 'Environmental engineer with 7 years developing sustainable solutions for industrial and municipal clients. Expert in environmental impact assessment, remediation technologies, and regulatory compliance. Led projects that reduced environmental footprint and achieved cost savings of $10M+. Strong background in water treatment, air quality management, and waste reduction. Professional Engineer license with experience in environmental consulting and project management.', 'jobseeker', '15921276-50e8-4a37-abff-157c38349f38'), ('David', 'Martinez', 'david.martinez@email.com', 'https://profilepics.com/users/010.jpg', 'https://cvs.com/david_martinez_cv.pdf', 'DevOps engineer with 8 years automating infrastructure and deployment processes. Expert in AWS, Docker, Kubernetes, and CI/CD pipelines. Reduced deployment time by 70% and improved system reliability across multiple organizations. Strong background in monitoring, security, and scalability. Experienced with microservices architecture and serverless computing. Passionate about site reliability engineering and cloud-native technologies. Seeking senior technical roles.', 'jobseeker', '16d77a56-6e7b-4b81-943c-824980515b92'), ('Technology', 'Partners', 'jobs@technologypartners.com', 'https://profilepics.com/orgs/060.jpg', '', 'Technology Partners is a systems integration firm helping enterprises modernize their technology infrastructure. We specialize in cloud migration, data analytics, and enterprise software implementation. Our team of 250+ consultants has deep expertise across multiple technology platforms and industries. We maintain partnerships with leading vendors including Microsoft, AWS, and Salesforce. Our mission is to help clients achieve digital transformation and competitive advantage.', 'organization', '1cb9d76e-33bd-48ff-a40f-89f382847a42'), ('Future', 'Labs', 'careers@futurelabs.com', 'https://profilepics.com/orgs/042.jpg', '', 'Future Labs is a research and development company focused on breakthrough technologies. We work on projects spanning artificial intelligence, quantum computing, biotechnology, and renewable energy. Our interdisciplinary team of scientists and engineers collaborate on solutions to global challenges. We partner with universities, government agencies, and private companies. Our culture encourages innovation, experimentation, and long-term thinking. Seeking research scientists, engineers, and project managers.', 'organization', '220c57b3-b53c-4940-8ba6-67c669c47970'), ('NextGen', 'Solutions', 'jobs@nextgensolutions.com', 'https://profilepics.com/orgs/012.jpg', '', 'NextGen Solutions provides innovative technology solutions for the healthcare industry. Founded by former medical professionals and tech executives, we understand the unique challenges facing healthcare organizations. Our products include electronic health records, telemedicine platforms, and AI-powered diagnostic tools. We serve over 500 healthcare facilities nationwide. Our mission is to improve patient outcomes through technology. Seeking healthcare IT specialists and software developers.', 'organization', '29ea82fc-3f2b-466c-92d0-a9f709504859'), ('Victoria', 'Mitchell', 'victoria.mitchell@email.com', 'https://profilepics.com/users/041.jpg', 'https://cvs.com/victoria_mitchell_cv.pdf', 'Legal counsel with 8+ years specializing in technology and intellectual property law. JD from top law school with focus on corporate law and contract negotiations. Advised startups and Fortune 500 companies on licensing agreements, M&A transactions, and regulatory compliance. Expert in privacy law, data protection, and employment matters. Led legal teams and managed outside counsel relationships. Seeking general counsel or senior legal roles.', 'jobseeker', '2e0974ea-e10d-42a3-a848-1473574d6554'), ('Jason', 'Adams', 'jason.adams@email.com', 'https://profilepics.com/users/034.jpg', 'https://cvs.com/jason_adams_cv.pdf', 'Cloud architect with 9+ years designing and implementing scalable cloud solutions. Expert in AWS, Azure, and Google Cloud platforms with multiple certifications. Led cloud migration projects worth $20M+ and reduced infrastructure costs by 50%. Strong background in microservices, containerization, and serverless architectures. Experience with infrastructure as code and DevOps practices. Passionate about emerging cloud technologies and their business applications.', 'jobseeker', '2e80142d-fa97-4dde-bf87-3ded7532be20'), ('Anthony', 'Wright', 'anthony.wright@email.com', 'https://profilepics.com/users/028.jpg', 'https://cvs.com/anthony_wright_cv.pdf', 'Database administrator with 8+ years managing large-scale database systems. Expert in SQL Server, Oracle, MySQL, and PostgreSQL environments. Optimized database performance for applications serving millions of users daily. Strong background in backup and recovery, security, and capacity planning. Led database migration projects and implemented high-availability solutions. Experience with cloud databases and big data technologies. Seeking senior DBA or data architect roles.', 'jobseeker', '2f65f919-0d8b-4f3d-a77c-e4ff04b2a209'), ('Emma', 'Taylor', 'emma.taylor@email.com', 'https://profilepics.com/users/011.jpg', 'https://cvs.com/emma_taylor_cv.pdf', 'Product manager with 6+ years driving product strategy and roadmap execution. MBA from top business school with technical background in computer science. Led product launches that generated $10M+ in revenue. Expert in user research, A/B testing, and data-driven decision making. Collaborated with engineering, design, and sales teams to deliver customer-focused solutions. Experience in B2B SaaS and mobile applications.', 'jobseeker', '301ae79a-699f-405e-9bea-97a5b6d115fd'), ('Innovation', 'Partners', 'talent@innovationpartners.com', 'https://profilepics.com/orgs/033.jpg', '', 'Innovation Partners is a strategy consulting firm focused on helping companies innovate and grow. We work with Fortune 500 companies to develop new products, enter new markets, and transform their business models. Our multidisciplinary team includes former executives, entrepreneurs, and subject matter experts. We use design thinking and agile methodologies to drive innovation. Our culture values intellectual curiosity, collaboration, and client impact. Seeking senior consultants and industry specialists.', 'organization', '32d70ef6-07a8-4eb9-a848-3d01921da992'), ('Manufacturing', 'Corp', 'careers@manufacturingcorp.com', 'https://profilepics.com/orgs/066.jpg', '', 'Manufacturing Corp is a leading manufacturer of industrial equipment and components serving global markets. We operate multiple facilities with advanced manufacturing technologies including robotics and automation. Our products are used in automotive, aerospace, and energy industries. We are committed to quality, innovation, and environmental sustainability. Our workforce of 2,000+ employees drives continuous improvement and operational excellence. Seeking engineers, technicians, and operations managers.', 'organization', '39bdeee8-93da-4524-ac17-e3ada84c1448'), ('Innovation', 'Hub', 'talent@innovationhub.com', 'https://profilepics.com/orgs/051.jpg', '', 'Innovation Hub is a technology incubator supporting early-stage startups in artificial intelligence, fintech, and healthtech. We provide workspace, mentorship, and access to investors and industry experts. Our program includes workshops, networking events, and pitch competitions. Alumni companies have achieved successful exits and raised significant venture funding. We foster a collaborative community of entrepreneurs and innovators. Seeking program managers, mentors, and business development professionals.', 'organization', '3ab90fcc-2272-4dd9-93f3-1b4b6912cfaf'), ('Lisa', 'Anderson', 'lisa.anderson@email.com', 'https://profilepics.com/users/008.jpg', 'https://cvs.com/lisa_anderson_cv.pdf', 'Financial analyst with CPA certification and 7 years in corporate finance. Expert in financial modeling, budgeting, and investment analysis. Worked with startups and public companies to optimize financial performance. Strong analytical skills with proficiency in Excel, SQL, and Python. Led multiple fundraising rounds totaling $25M. Experience in due diligence, mergers, and acquisitions. Looking for CFO or senior finance roles.', 'jobseeker', '3cf9f89a-e469-4dc6-9bfa-0bb4907e93cf'), ('Smart', 'Solutions', 'team@smartsolutions.com', 'https://profilepics.com/orgs/024.jpg', '', 'Smart Solutions is a management consulting firm specializing in business strategy and operational excellence. We help organizations improve performance, reduce costs, and drive growth. Our consultants have deep expertise across industries including manufacturing, retail, and financial services. We use data-driven approaches and proven methodologies to deliver measurable results. Our culture emphasizes collaboration, innovation, and client success. Seeking experienced consultants and project managers.', 'organization', '3f82e0aa-ade9-4208-9a21-d28712498d5e'), ('Financial', 'Services', 'hiring@financialservices.com', 'https://profilepics.com/orgs/054.jpg', '', 'Financial Services is a comprehensive financial planning and investment management firm serving high-net-worth individuals and families. We provide personalized financial strategies including investment management, retirement planning, and estate planning. Our team of certified financial planners and investment advisors manages over $2B in client assets. We pride ourselves on building long-term relationships and delivering exceptional client service. Seeking financial advisors and portfolio managers.', 'organization', '4009239b-f413-42e4-811f-d37aeb85c452'), ('Innovation', 'Labs', 'talent@innovationlabs.com', 'https://profilepics.com/orgs/009.jpg', '', 'Innovation Labs is a research and development company focused on emerging technologies. We specialize in AI, blockchain, IoT, and quantum computing solutions. Our team of 150+ researchers and engineers work on cutting-edge projects for government and enterprise clients. We foster a collaborative environment that encourages experimentation and breakthrough thinking. Seeking PhD-level researchers, software architects, and technical leads to join our growing team.', 'organization', '405e980c-692f-4af5-acf1-e59f3079f733'), ('Jordan', 'Carter', 'jordan.carter@email.com', 'https://profilepics.com/users/040.jpg', 'https://cvs.com/jordan_carter_cv.pdf', 'Training specialist with 7 years developing and delivering educational programs. Designed training curricula for technical and soft skills that improved employee performance by 40%. Expert in instructional design, e-learning platforms, and adult learning principles. Strong presentation and facilitation skills with experience training diverse audiences. Created onboarding programs that reduced time-to-productivity for new hires. Seeking learning and development leadership roles.', 'jobseeker', '406429f3-d802-4ff3-a7ce-efe968e22754'), ('Annie', 'Coleman', 'annie.coleman@email.com', 'https://profilepics.com/users/098.jpg', 'https://cvs.com/annie_coleman_cv.pdf', 'Hairstylist and salon owner with 12 years in cosmetology and business management. Licensed cosmetologist with expertise in cutting, coloring, and styling for diverse clientele. Built successful salon business with loyal customer base and positive reputation. Strong creative skills with knowledge of latest trends, techniques, and products. Experience in staff management, inventory control, and customer service. Seeking opportunities to expand salon operations or join upscale establishments.', 'jobseeker', '415da071-0035-48f3-b614-c4eafba10d8c'), ('Dennis', 'Cook', 'dennis.cook@email.com', 'https://profilepics.com/users/064.jpg', 'https://cvs.com/dennis_cook_cv.pdf', 'Industrial engineer with 8 years optimizing manufacturing processes and facility operations. Expert in lean manufacturing, six sigma methodologies, and process improvement. Led initiatives that increased productivity by 35% and reduced waste by 50% in manufacturing environments. Strong analytical skills with experience in data analysis, simulation modeling, and cost-benefit analysis. Professional Engineer license with background in automotive and aerospace industries.', 'jobseeker', '41e2fc36-0669-451a-94ad-f078e7453bfd'), ('Kevin', 'Clark', 'kevin.clark@email.com', 'https://profilepics.com/users/019.jpg', 'https://cvs.com/kevin_clark_cv.pdf', 'Business analyst with 5+ years bridging business requirements and technical solutions. Strong background in process improvement, requirements gathering, and stakeholder management. Led digital transformation projects that increased operational efficiency by 30%. Proficient in SQL, Tableau, and various business intelligence tools. Experience across finance, healthcare, and retail industries. Excellent communication skills and ability to translate complex technical concepts for business audiences.', 'jobseeker', '4423d0e8-fad3-4d42-9cfc-f25a6901d3af'), ('Lillian', 'Ross', 'lillian.ross@email.com', 'https://profilepics.com/users/095.jpg', 'https://cvs.com/lillian_ross_cv.pdf', 'Bank teller and customer service representative with 5 years in financial services. Expert in cash handling, account transactions, and customer relationship management. Processed thousands of financial transactions while maintaining accuracy and compliance with banking regulations. Strong communication skills with ability to explain financial products and resolve customer inquiries. Cross-trained in loan processing, safe deposit box operations, and new account opening procedures.', 'jobseeker', '463f5228-94ed-4472-817c-1387e3ebe5d5'), ('Michael', 'Brown', 'michael.brown@email.com', 'https://profilepics.com/users/004.jpg', 'https://cvs.com/michael_brown_cv.pdf', 'Data scientist with 6 years of experience in machine learning and statistical analysis. PhD in Computer Science with focus on artificial intelligence. Worked with large datasets in retail, finance, and healthcare sectors. Expert in Python, R, SQL, and various ML frameworks including TensorFlow and PyTorch. Published 12 research papers and presented at international conferences. Passionate about solving complex problems through data-driven insights.', 'jobseeker', '47a8b47b-3d2d-4232-9809-35aba65d8782'), ('Samantha', 'Nelson', 'samantha.nelson@email.com', 'https://profilepics.com/users/038.jpg', 'https://cvs.com/samantha_nelson_cv.pdf', 'Research scientist with PhD in Materials Science and 8 years in R&D. Published 25+ research papers in peer-reviewed journals and holds 5 patents. Expert in nanotechnology, materials characterization, and product development. Led research teams that developed breakthrough materials for aerospace and electronics applications. Strong grant writing skills with experience securing $5M+ in research funding. Seeking senior R&D or technical leadership roles.', 'jobseeker', '4bdec5d2-b62d-4fd7-85f8-0ea7b12bb223'), ('Ralph', 'Gray', 'ralph.gray@email.com', 'https://profilepics.com/users/079.jpg', 'https://cvs.com/ralph_gray_cv.pdf', 'Police officer with 13 years in law enforcement and public safety. Bachelor degree in Criminal Justice with specialized training in investigations, community policing, and emergency response. Served in patrol, detective, and supervisory roles while maintaining excellent service record. Strong communication and problem-solving skills with experience in conflict resolution and crisis management. Committed to building positive community relationships and ensuring public safety.', 'jobseeker', '4f813399-4d9a-4842-8abb-f893844456bd'), ('Arthur', 'Torres', 'arthur.torres@email.com', 'https://profilepics.com/users/076.jpg', 'https://cvs.com/arthur_torres_cv.pdf', 'Electrical engineer with 11 years designing power systems and electrical infrastructure. Professional Engineer license with expertise in power generation, transmission, and distribution systems. Led engineering projects for utilities and industrial clients worth $50M+ in capital investment. Strong technical skills in electrical design software, power system analysis, and renewable energy integration. Experience with smart grid technologies and energy storage systems.', 'jobseeker', '5594e353-7b89-403e-8a3f-3d2754216658'), ('Consulting', 'Group', 'careers@consultinggroup.com', 'https://profilepics.com/orgs/048.jpg', '', 'Consulting Group is a management consulting firm serving Fortune 500 companies across various industries. We specialize in strategy development, organizational transformation, and operational improvement. Our consultants have deep expertise in finance, technology, and operations. We use data-driven methodologies and proven frameworks to deliver measurable results. Our collaborative culture emphasizes professional development and client success. Seeking experienced consultants, analysts, and project managers.', 'organization', '5714d2e5-460d-46ae-87cc-38d9f0b5b8ad'), ('Kenneth', 'Cox', 'kenneth.cox@email.com', 'https://profilepics.com/users/073.jpg', 'https://cvs.com/kenneth_cox_cv.pdf', 'Chef and restaurant manager with 8 years in culinary arts and hospitality management. Culinary arts degree with expertise in menu development, food cost control, and kitchen operations. Managed restaurants with annual revenue of $5M+ while maintaining high customer satisfaction and profit margins. Strong leadership skills with experience training kitchen staff and implementing food safety protocols. Specialized in farm-to-table cuisine and sustainable food practices.', 'jobseeker', '591c6adc-5ba3-4a8a-8400-9615aeb2f7bf'), ('Financial', 'Institution', 'careers@financialinstitution.com', 'https://profilepics.com/orgs/096.jpg', '', 'Financial Institution is a community bank serving local businesses and residents for over 50 years. We provide comprehensive banking services including checking and savings accounts, loans, and investment services. Our commitment to personalized service and community involvement sets us apart from larger banks. We maintain strong relationships with local businesses and support community development initiatives. Seeking banking professionals dedicated to excellent customer service and community banking.', 'organization', '5b33eda9-3285-4dc1-9871-fc4c9f97a210'), ('Amanda', 'Garcia', 'amanda.garcia@email.com', 'https://profilepics.com/users/014.jpg', 'https://cvs.com/amanda_garcia_cv.pdf', 'Sales manager with 8+ years exceeding revenue targets in B2B technology sales. Consistently achieved 120%+ of quota and built territory worth $5M annually. Expert in consultative selling, relationship building, and complex deal negotiations. Led sales teams of 10+ representatives and implemented CRM systems that improved conversion rates. Strong presentation and communication skills. Seeking VP of Sales or similar leadership roles.', 'jobseeker', '5b4b4a52-5052-45d4-9966-1c5033ff2296'), ('Stephen', 'Turner', 'stephen.turner@email.com', 'https://profilepics.com/users/046.jpg', 'https://cvs.com/stephen_turner_cv.pdf', 'Mechanical engineer with 10+ years designing and developing consumer products. Expert in CAD design, prototyping, and manufacturing processes. Led product development teams that launched successful products generating $25M+ in revenue. Strong background in materials science, quality control, and regulatory compliance. Experience with sustainable design and lifecycle analysis. Holds multiple patents and has won industry awards for innovative designs.', 'jobseeker', '609d1e41-de9e-469d-ba1d-55657638bf53'), ('Patricia', 'Stewart', 'patricia.stewart@email.com', 'https://profilepics.com/users/056.jpg', 'https://cvs.com/patricia_stewart_cv.pdf', 'Nurse practitioner with 10+ years providing comprehensive healthcare services. MSN degree with certifications in family practice and acute care. Managed patient caseloads in clinical, hospital, and community health settings. Strong diagnostic and treatment skills with focus on preventive care and patient education. Led quality improvement initiatives that enhanced patient outcomes and satisfaction. Experience with electronic health records and telemedicine platforms.', 'jobseeker', '63b5fea8-221d-4181-a7f6-8f5cf05d5791'), ('TechCorp', 'Solutions', 'hr@techcorpsolutions.com', 'https://profilepics.com/orgs/003.jpg', '', 'TechCorp Solutions is a leading software development company specializing in enterprise solutions and cloud infrastructure. Founded in 2010, we serve Fortune 500 companies across various industries. Our team of 200+ professionals delivers cutting-edge technology solutions using agile methodologies. We value innovation, collaboration, and continuous learning. Currently expanding our development teams and seeking talented engineers, designers, and project managers.', 'organization', '6430c751-9ef9-4d3d-b272-5753f8707f73'), ('Future', 'Systems', 'careers@futuresystems.com', 'https://profilepics.com/orgs/018.jpg', '', 'Future Systems is an enterprise software company providing ERP and CRM solutions to mid-market businesses. Our cloud-based platform serves over 1,000 customers worldwide and processes billions of transactions annually. We focus on scalability, security, and user experience. Our engineering team uses modern technologies and agile development practices. We offer competitive compensation, flexible work arrangements, and professional development opportunities. Seeking software engineers, product managers, and customer success specialists.', 'organization', '67951ec7-0ad5-4f36-88ff-9b9aa32a6d71'), ('Sarah', 'Johnson', 'sarah.johnson@email.com', 'https://profilepics.com/users/002.jpg', 'https://cvs.com/sarah_johnson_cv.pdf', 'Marketing professional with expertise in digital campaigns and brand strategy. Successfully managed marketing budgets exceeding $2M and increased brand awareness by 45% across multiple channels. Specializes in social media marketing, content creation, and data analytics. Proven track record in B2B and B2C environments. Strong communication skills and ability to work with diverse teams. Currently seeking opportunities in tech startups.', 'jobseeker', '6838e61b-4882-4517-956f-41c65b1e0592'), ('John', 'Smith', 'john.smith@email.com', 'https://profilepics.com/users/001.jpg', 'https://cvs.com/john_smith_cv.pdf', 'Experienced software engineer with 8+ years in full-stack development. Passionate about creating scalable web applications using React, Node.js, and Python. Led multiple cross-functional teams and delivered projects on time. Strong background in agile methodologies and cloud computing. Always eager to learn new technologies and contribute to innovative solutions. Experience includes fintech, healthcare, and e-commerce domains.', 'jobseeker', '68c1b484-30b5-45fe-87d5-e52e6541f60e'), ('Healthcare', 'Systems', 'careers@healthcaresystems.com', 'https://profilepics.com/orgs/057.jpg', '', 'Healthcare Systems is a regional healthcare provider operating multiple hospitals and clinical facilities. We serve over 500,000 patients annually and employ 5,000+ healthcare professionals. We are committed to providing high-quality, compassionate care while advancing medical research and education. Our facilities include specialty centers for cardiology, oncology, and neuroscience. We invest heavily in technology and staff development. Seeking nurses, physicians, and healthcare administrators.', 'organization', '6e32a400-9f5b-44b7-a793-bc7c85d723de'), ('Hospitality', 'Group', 'jobs@hospitalitygroup.com', 'https://profilepics.com/orgs/075.jpg', '', 'Hospitality Group operates a portfolio of hotels, restaurants, and event venues across the region. We are committed to providing exceptional guest experiences while maintaining operational excellence. Our properties include luxury hotels, casual dining restaurants, and conference facilities. We employ over 1,500 hospitality professionals and pride ourselves on service quality and employee development. Seeking hotel managers, chefs, and event coordinators with passion for hospitality.', 'organization', '7087c12c-faa3-43ea-9275-01348e37fa93'), ('Janice', 'Ramirez', 'janice.ramirez@email.com', 'https://profilepics.com/users/080.jpg', 'https://cvs.com/janice_ramirez_cv.pdf', 'Marketing coordinator with 5 years supporting integrated marketing campaigns and brand initiatives. Expert in digital marketing, event planning, and campaign execution. Managed marketing projects that increased brand awareness by 40% and generated qualified leads for sales teams. Strong organizational skills with experience in project management, vendor relations, and budget administration. Proficient in marketing automation platforms and analytics tools.', 'jobseeker', '718756ea-f763-46f0-b430-15c1a1e95457'), ('Tech', 'Pioneers', 'hiring@techpioneers.com', 'https://profilepics.com/orgs/021.jpg', '', 'Tech Pioneers is a startup accelerator and venture capital firm investing in early-stage technology companies. We provide funding, mentorship, and resources to help entrepreneurs build successful businesses. Our portfolio includes over 100 companies across various sectors including fintech, healthtech, and AI. We have experienced partners who are former founders and executives from major tech companies. Seeking investment analysts, portfolio managers, and startup advisors.', 'organization', '7411be99-38f4-4afc-96df-ed81786f7319'), ('Teresa', 'Cooper', 'teresa.cooper@email.com', 'https://profilepics.com/users/068.jpg', 'https://cvs.com/teresa_cooper_cv.pdf', 'Clinical research coordinator with 7 years managing clinical trials for pharmaceutical and biotech companies. Expert in Good Clinical Practice guidelines, regulatory compliance, and patient recruitment. Coordinated over 20 clinical studies across multiple therapeutic areas including oncology, cardiology, and infectious diseases. Strong organizational skills with attention to detail and ability to work with diverse stakeholders including investigators, sponsors, and regulatory agencies.', 'jobseeker', '762dae36-27f2-4329-bb8e-8bd01380faa5'), ('Community', 'Services', 'hiring@communityservices.com', 'https://profilepics.com/orgs/078.jpg', '', 'Community Services is a non-profit organization providing social services to underserved populations. We offer programs including housing assistance, job training, mental health services, and youth development. Our mission is to strengthen communities by empowering individuals and families to achieve self-sufficiency. We serve over 10,000 clients annually through multiple program locations. Seeking social workers, case managers, and program coordinators committed to social justice.', 'organization', '77e8a17a-9ac8-4101-886d-8bff3072f16d'), ('Jennifer', 'Davis', 'jennifer.davis@email.com', 'https://profilepics.com/users/005.jpg', 'https://cvs.com/jennifer_davis_cv.pdf', 'UX/UI designer with 5+ years creating intuitive digital experiences. Strong background in user research, wireframing, and prototyping. Proficient in Figma, Sketch, and Adobe Creative Suite. Led design for mobile apps with over 1M downloads. Collaborated with product managers and developers to deliver user-centered solutions. Experience in fintech, e-commerce, and SaaS products. Committed to accessibility and inclusive design principles.', 'jobseeker', '78ff94a4-27b8-45d8-9c84-3ee9594ad9d0'), ('Digital', 'Marketing', 'jobs@digitalmarketing.com', 'https://profilepics.com/orgs/045.jpg', '', 'Digital Marketing is a full-service digital marketing agency serving clients across multiple industries. We specialize in search engine optimization, pay-per-click advertising, social media marketing, and conversion optimization. Our data-driven approach has helped clients achieve average ROI of 400% on marketing spend. Our team of 40+ specialists stays current with latest digital marketing trends and technologies. Seeking digital marketers, analysts, and account managers.', 'organization', '7b6e6761-3f70-47ff-9efd-dabcc89a08bb'), ('Digital', 'Dynamics', 'recruiting@digitaldynamics.com', 'https://profilepics.com/orgs/015.jpg', '', 'Digital Dynamics is a full-service digital agency serving clients across multiple industries. We specialize in web development, mobile applications, digital marketing, and e-commerce solutions. Our creative team of 80+ professionals delivers award-winning campaigns and innovative digital experiences. We work with brands ranging from local businesses to international corporations. Our culture values creativity, collaboration, and continuous learning. Seeking developers, designers, and digital strategists.', 'organization', '7c21a359-f7fa-41a5-8230-263cc3f152b2'), ('Sandra', 'Richardson', 'sandra.richardson@email.com', 'https://profilepics.com/users/071.jpg', 'https://cvs.com/sandra_richardson_cv.pdf', 'Elementary school teacher with 10 years educating students in grades K-5. Masters degree in Education with specialization in curriculum development and classroom management. Created innovative lesson plans that improved student engagement and academic performance. Strong communication skills with experience in parent-teacher conferences, professional development,